// Evaluates every check, keeps per-target state between runs and decides what
// to report. Always returns exactly one item, so a run never ends silently.
const settings = $('Settings').first().json;
const targets = $('Split targets').all().map((item) => item.json);
const checks = $input.all();

const positiveInt = (value, fallback) => {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : fallback;
};
const failuresBeforeAlert = Math.max(1, positiveInt(settings.failuresBeforeAlert, 2));
const reminderMs = positiveInt(settings.reminderMinutes, 60) * 60 * 1000;

const state = $getWorkflowStaticData('global');
if (!state.targets || typeof state.targets !== 'object' || Array.isArray(state.targets)) state.targets = {};
const now = Date.now();

const results = checks.map((check, index) => {
  const paired = check.pairedItem;
  const targetIndex = Array.isArray(paired) ? paired[0]?.item : paired?.item;
  const target = targets[Number.isInteger(targetIndex) ? targetIndex : index] || {};
  const name = String(target.name || target.url || 'Target ' + (index + 1));
  const url = String(target.url || '');
  const keyword = String(target.expectedKeyword || '');
  const json = check.json || {};
  let up = false;
  let detail = '';
  if (!/^https?:\/\/\S+$/i.test(url)) {
    detail = 'Invalid URL in Settings';
  } else if (json.error) {
    const msg = typeof json.error === 'string' ? json.error : (json.error.message || 'Request failed');
    detail = 'No response: ' + String(msg).slice(0, 200);
  } else {
    const status = Number(json.statusCode);
    const body = typeof json.data === 'string' ? json.data : JSON.stringify(json.data ?? '');
    if (status === 429) detail = 'HTTP 429 - the target is rate limiting the monitor';
    else if (!(status >= 200 && status < 400)) detail = 'HTTP ' + (Number.isFinite(status) ? status : 'unknown');
    else if (keyword && !body.includes(keyword)) detail = 'HTTP ' + status + ' but keyword "' + keyword + '" not found';
    else { up = true; detail = 'HTTP ' + status; }
  }
  return { key: name + ' ' + url, name, url, up, detail };
});

const events = [];
const seen = new Set();
for (const r of results) {
  seen.add(r.key);
  const s = state.targets[r.key] && typeof state.targets[r.key] === 'object' ? state.targets[r.key] : { failures: 0, alerted: false, lastAlertAt: 0 };
  if (r.up) {
    if (s.alerted) events.push({ type: 'RECOVERED', r });
    state.targets[r.key] = { failures: 0, alerted: false, lastAlertAt: 0 };
    continue;
  }
  const failures = (Number(s.failures) || 0) + 1;
  let alerted = s.alerted === true;
  let lastAlertAt = Number(s.lastAlertAt) || 0;
  if (!alerted && failures >= failuresBeforeAlert) {
    events.push({ type: 'DOWN', r });
    alerted = true;
    lastAlertAt = now;
  } else if (alerted && reminderMs > 0 && now - lastAlertAt >= reminderMs) {
    events.push({ type: 'STILL DOWN', r });
    lastAlertAt = now;
  }
  state.targets[r.key] = { failures, alerted, lastAlertAt };
}
for (const key of Object.keys(state.targets)) if (!seen.has(key)) delete state.targets[key];

const escapeHtml = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const down = events.filter((e) => e.type !== 'RECOVERED').length;
const recovered = events.length - down;
const parts = [];
if (down) parts.push(down + ' down');
if (recovered) parts.push(recovered + ' recovered');
const subject = parts.length ? ('Uptime: ' + parts.join(', ') + ' - ' + events.map((e) => e.r.name).join(', ')).replace(/[\r\n]+/g, ' ').slice(0, 180) : '';
const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#1f2328;max-width:640px;width:100%;box-sizing:border-box;overflow-wrap:anywhere;word-break:break-word;"><table role="presentation" style="width:100%;table-layout:fixed;border-collapse:collapse">'
  + events.map((e) => '<tr><td style="width:22%;padding:4px 12px 4px 0;vertical-align:top;font-weight:bold;overflow-wrap:anywhere;word-break:break-word;color:' + (e.type === 'RECOVERED' ? '#1a7f37' : '#cf222e') + '">' + e.type + '</td><td style="width:38%;padding:4px 12px 4px 0;vertical-align:top;overflow-wrap:anywhere;word-break:break-word;">' + escapeHtml(e.r.name) + '<br><span style="color:#57606a;font-size:12px">' + escapeHtml(e.r.url) + '</span></td><td style="padding:4px 0;vertical-align:top;overflow-wrap:anywhere;word-break:break-word;">' + escapeHtml(e.r.detail) + '</td></tr>').join('')
  + '</table><p style="color:#57606a;font-size:12px">Checked ' + results.length + ' target(s) at ' + new Date(now).toISOString() + ' (UTC). An outage is reported after ' + failuresBeforeAlert + ' failed check(s) in a row.</p></div>';
const text = events.map((e) => e.type + ': ' + e.r.name + ' (' + e.r.url + ') - ' + e.r.detail).join('\n');

return [{ json: { alertNeeded: events.length > 0, subject, html, text, checked: results.length, up: results.filter((r) => r.up).length, results } }];
